cruiser_top = false

function randomize(position)
    return randomize_scaled(position, 0.05)
end

function randomize_scaled(position, scale)
    position.x = position.x + (math.random() - 0.5) * scale
    position.z = position.z + (math.random() - 0.5) * scale
    return position
end

function below(position)
    return randomize(raycast(position))
end

function cupboard_or(cupboard_pos, fallback_pos)
    if unlockables[UNLOCKABLE_CUPBOARD] then
        return ItemPos(randomize_scaled(raycast(cupboard_pos, TRANSFORM_CUPBOARD), 0.02)):with_parent(PARENT_CUPBOARD)
    elseif fallback_pos == nil then
        return nil
    else
        return randomize_scaled(raycast(fallback_pos), 0.02)
    end
end

function cupboard_or_rot(cupboard_pos, fallback_pos, fallback_rot)
    if unlockables[UNLOCKABLE_CUPBOARD] then
        return ItemPos(randomize_scaled(raycast(cupboard_pos, TRANSFORM_CUPBOARD), 0.02)):with_parent(PARENT_CUPBOARD)
    else
        return ItemPos(randomize_scaled(raycast(fallback_pos), 0.02)):with_rotation(fallback_rot)
    end
end

function first_x_on_cruiser(item, x, cruiser_pos, cruiser_top_pos, cruiser_rot, fallback_pos)
    if unlockables[UNLOCKABLE_CRUISER] and item.index - 1 < x and item.index < item.count then
        return ItemPos((function()
            if cruiser_top then
                return cruiser_top_pos
            else
                return cruiser_pos
            end
        end)()):with_parent(PARENT_CRUISER):with_rotation(cruiser_rot)
    else
        return fallback_pos
    end
end

retval = {}

-- Y
CUPBOARD_ABOVE = 3.2;
CUPBOARD_TOP = 2.4;
CUPBOARD_MIDDLE_1 = 2;
CUPBOARD_MIDDLE_2 = 1.5;
CUPBOARD_BOTTOM = 0.5;

-- Y
CRUISER_ABOVE = 2.4;
CRUISER_TOP = 1.17;
CRUISER_MIDDLE = 0.4;
CRUISER_BOTTOM = -0.12;
CRUISER_FLOOR = -0.5;

