-- TODO: POSITION_TRASH = ItemPos(nil)

max_large = 1
max_small = 1
if moon.id == 3 then
    for i, v in pairs(items) do
        if not (v.name == "ClipboardManual" or v.name == "StickyNoteItem" or v.name == "ZeddogPlushie" or v.name == "KnifeItem" or v.name == "ShotgunItem") then
            -- skip these items, they are not included later
            if v.large then
                max_large = math.max(v.value, max_large)
            else
                max_small = math.max(v.value, max_small)
            end
        end
    end
end

