                shotguns_on_cruiser = shotguns_on_cruiser + 1
                retval[i] = ItemPos((function()
                    if cruiser_top then
                        return nil
                    else
                        return Vector3(CRUISER_RIGHT + 0.04, CRUISER_TOP, -1.2)
